 const match = router([...itemRoutes, ...batchRoutes, ...orderRoutes, ...kitchenRoutes, ...planningRoutes, ...safetyRoutes]);

+function requestLanguage(headers) {
+  let lang = config.defaultLanguage;
+  let bestQuality = 0;
+  for (const [name, value] of Object.entries(headers)) {
+    if (name.toLowerCase() !== "accept-language") continue;
+    for (const entry of String(value).split(",")) {
+      const preference = /^([a-z]{2})(?:-[a-z0-9]{1,8})*(?:\s*;\s*q\s*=\s*(0(?:\.\d{0,3})?|1(?:\.0{0,3})?|\.\d{1,3}))?$/i.exec(entry.trim());
+      if (!preference) continue;
+      const candidate = preference[1].toLowerCase();
+      const quality = Number(preference[2] ?? 1);
+      if (LANGUAGES.includes(candidate) && quality > bestQuality) {
+        lang = candidate;
+        bestQuality = quality;
+      }
+    }
+  }
+  return lang;
+}
